# helpers -----------------------------------------------------------------
def C(src, loc, lvl): return dict(src=src, loc=loc, level=lvl)
def A(attr, **values): return dict(attribute=attr, values=[dict(value=k, effect=v[0], cite=v[1] if len(v) > 1 else None) for k, v in values.items()])

PFA = lambda loc, lvl="read": C("S1", loc, lvl)
BEN = lambda loc, lvl="toc": C("S2", loc, lvl)
BS = lambda v, lvl="read": C("S3", f"Brihat Samhita 68.{v}", lvl)
WEB = lambda loc: C("S7", loc, "web")

def F(id, kind, en, hi, roman, summary, attrs, cites, tier=None, aliases=None, app_safe=None, avoid=None, sens=None, region=None, detect="", conf="medium", note=None):
    d = dict(id=id, kind=kind, name_en=en, name_hi=hi, name_roman=roman, tier=tier, aliases=aliases or [], summary=summary,
             attributes=attrs, citations=cites, app_safe_reading=app_safe, avoid_claims=avoid or [], sensitivity=sens or [],
             region_ref=region, auto_detect=detect, confidence=conf)
    if note: d["note"] = note
    return d

